import Foundation

struct GreetingGeneratorV2: GreetingGenerator {
    var buttonTitle: String { "Greet (new!)" }

    func generateGreeting(for name: String) -> String { 
        var reversed = ""
        for char in longString {
            reversed.insert(char, at: reversed.startIndex)
        }
        return "Hello, \(name)! Your lucky number is \(reversed.count)"
    }
}

